WITH base AS (SELECT *, ROUND(rating, 0) AS rating_rounded FROM suppliers WHERE supplier_name IS NOT NULL), rating_rounded_bucket_summary AS (SELECT CASE WHEN rating_rounded >= 75 THEN 'high' WHEN rating_rounded >= 37 THEN 'mid' ELSE 'low' END AS rating_rounded_bucket, ROUND(STDDEV(rating_rounded), 2) AS stddev_rating_rounded FROM base GROUP BY CASE WHEN rating_rounded >= 75 THEN 'high' WHEN rating_rounded >= 37 THEN 'mid' ELSE 'low' END) SELECT rating_rounded_bucket, stddev_rating_rounded FROM rating_rounded_bucket_summary WHERE stddev_rating_rounded > 74 ORDER BY stddev_rating_rounded ASC, rating_rounded_bucket ASC LIMIT 3
